/*
 * option-lab.js — Black-Scholes, greeks, decay and profit ladders, in the
 * browser, with no dependencies and no network.
 *
 * This is a JavaScript port of pwb_toolbox/options/{greeks,decay}.py, kept
 * deliberately faithful: static/option-lab.test.js checks every function
 * against values generated by the Python module, so the two cannot drift into
 * disagreeing about the same contract. Where this file adds something Python
 * does not have (rho, the ladders, the touch probabilities) the test pins it
 * against a closed form or a known identity instead.
 *
 * Conventions, all matching the Python side because they are the numbers a
 * broker screen shows:
 *
 *   theta  per calendar day, not annualized
 *   vega   per one percentage point of implied volatility
 *   rho    per one percentage point of the risk-free rate
 *   vol    a decimal — 0.28 means 28%
 *   days   calendar days to expiry, and may be fractional
 *
 * American early exercise is not modeled, exactly as in the Python module. For
 * long calls on non-dividend payers the European price is exact; for puts it
 * understates slightly. A deep in-the-money European put prices below intrinsic
 * and so shows negative extrinsic and positive theta — correct here, and not a
 * bug to be clamped away.
 */
(function (root, factory) {
  const api = factory();
  if (typeof module === "object" && module.exports) module.exports = api;
  else root.OptionLab = api;
})(typeof self !== "undefined" ? self : this, function () {
  "use strict";

  const DAYS_PER_YEAR = 365;
  const TRADING_DAYS = 252;
  const SQRT_2PI = Math.sqrt(2 * Math.PI);

  /*
   * Hart's double-precision cumulative normal. The textbook Abramowitz &
   * Stegun 7.1.26 is only good to ~1.5e-7, which is enough for a price and not
   * enough to reconcile against scipy in a test to 1e-9. This is accurate to
   * roughly machine epsilon across the whole range.
   */
  function normCdf(x) {
    const z = Math.abs(x);
    let c;
    if (z > 37) {
      c = 0;
    } else {
      const e = Math.exp(-z * z / 2);
      if (z < 7.07106781186547) {
        let b = 3.52624965998911e-2 * z + 0.700383064443688;
        b = b * z + 6.37396220353165;
        b = b * z + 33.912866078383;
        b = b * z + 112.079291497871;
        b = b * z + 221.213596169931;
        b = b * z + 220.206867912376;
        let d = 8.83883476483184e-2 * z + 1.75566716318264;
        d = d * z + 16.064177579207;
        d = d * z + 86.7807322029461;
        d = d * z + 296.564248779674;
        d = d * z + 637.333633378831;
        d = d * z + 793.826512519948;
        d = d * z + 440.413735824752;
        c = e * b / d;
      } else {
        let b = z + 0.65;
        b = z + 4 / b;
        b = z + 3 / b;
        b = z + 2 / b;
        b = z + 1 / b;
        c = e / (b * 2.506628274631);
      }
    }
    return x > 0 ? 1 - c : c;
  }

  function normPdf(x) {
    return Math.exp(-x * x / 2) / SQRT_2PI;
  }

  /*
   * Price one contract and return every sensitivity, per share.
   *
   * Returns null rather than throwing on inputs that have no price — an expiry
   * in the past, a zero strike, a volatility of zero. The caller is usually a
   * half-filled form, and a null propagates into a blank cell where an
   * exception would blank the whole page.
   */
  function blackScholes(spot, strike, days, vol, rate, kind) {
    rate = rate == null ? 0.045 : rate;
    kind = (kind || "call").toLowerCase();
    if (kind !== "call" && kind !== "put") return null;
    if (!(spot > 0) || !(strike > 0) || !(vol > 0) || !(days > 0)) return null;

    const years = days / DAYS_PER_YEAR;
    const sqrtT = Math.sqrt(years);
    const sigmaSqrtT = vol * sqrtT;
    const d1 = (Math.log(spot / strike) + (rate + 0.5 * vol * vol) * years) / sigmaSqrtT;
    const d2 = d1 - sigmaSqrtT;
    const discount = Math.exp(-rate * years);
    const pdf1 = normPdf(d1);

    const decayTerm = -spot * pdf1 * vol / (2 * sqrtT);
    const gamma = pdf1 / (spot * vol * sqrtT);
    const vega = spot * pdf1 * sqrtT / 100;

    let price, delta, thetaAnnual, intrinsic, rho;
    if (kind === "call") {
      price = spot * normCdf(d1) - strike * discount * normCdf(d2);
      delta = normCdf(d1);
      thetaAnnual = decayTerm - rate * strike * discount * normCdf(d2);
      intrinsic = Math.max(spot - strike, 0);
      rho = strike * years * discount * normCdf(d2) / 100;
    } else {
      price = strike * discount * normCdf(-d2) - spot * normCdf(-d1);
      delta = normCdf(d1) - 1;
      thetaAnnual = decayTerm + rate * strike * discount * normCdf(-d2);
      intrinsic = Math.max(strike - spot, 0);
      rho = -strike * years * discount * normCdf(-d2) / 100;
    }

    return {
      price: price,
      delta: delta,
      gamma: gamma,
      theta: thetaAnnual / DAYS_PER_YEAR,
      vega: vega,
      rho: rho,
      intrinsic: intrinsic,
      extrinsic: price - intrinsic,
      d1: d1,
      d2: d2,
    };
  }

  /*
   * Back out the volatility that reprices `price`.
   *
   * The premium actually paid is the observable fact; a volatility typed in
   * from elsewhere is not. Solving backwards keeps every greek consistent with
   * the contract in front of you. Returns null when no volatility reproduces
   * the price — usually a stale or crossed quote.
   */
  function impliedVol(price, spot, strike, days, rate, kind, bracket) {
    let lo = (bracket && bracket[0]) || 1e-4;
    let hi = (bracket && bracket[1]) || 5;
    const at = v => {
      const g = blackScholes(spot, strike, days, v, rate, kind);
      return g && g.price;
    };
    const pLo = at(lo), pHi = at(hi);
    if (pLo == null || pHi == null) return null;
    if (!(pLo <= price && price <= pHi)) return null;

    for (let i = 0; i < 200; i++) {
      const mid = 0.5 * (lo + hi);
      const p = at(mid);
      if (Math.abs(p - price) < 1e-10) return mid;
      if (p < price) lo = mid; else hi = mid;
    }
    return 0.5 * (lo + hi);
  }

  /* One standard deviation of underlying movement over `days` sessions.
     Trading days, not calendar days — price only moves when the market is open. */
  function expectedMove(spot, vol, days) {
    if (!(days > 0)) return 0;
    return spot * vol * Math.sqrt(days / TRADING_DAYS);
  }

  /* Daily breakeven move as a fraction of a normal daily move. 0.10 means the
     underlying must deliver a tenth of a typical day's range, your way, every
     day, just to stand still. */
  function hurdleRatio(spot, strike, days, vol, rate, kind) {
    const g = blackScholes(spot, strike, days, vol, rate, kind);
    if (!g || g.delta === 0) return Infinity;
    const daily = expectedMove(spot, vol, 1);
    if (daily === 0) return Infinity;
    return (Math.abs(g.theta) / Math.abs(g.delta)) / daily;
  }

  /*
   * Underlying price at which the option is worth `target`.
   *
   * Solved numerically rather than from delta, so the answer accounts for both
   * the curvature of the option and the decay still to be paid between now and
   * `days`. Returns null when the target is unreachable at that horizon.
   */
  function breakevenSpot(target, strike, days, vol, rate, kind) {
    let lo = 0.01 * strike, hi = 100 * strike;
    const at = s => {
      const g = blackScholes(s, strike, days, vol, rate, kind);
      return g && g.price;
    };
    const increasing = (kind || "call").toLowerCase() === "call";
    const pLo = at(lo), pHi = at(hi);
    if (pLo == null || pHi == null) return null;
    const best = increasing ? pHi : pLo;
    const worst = increasing ? pLo : pHi;
    if (target > best || target < worst) return null;

    for (let i = 0; i < 200; i++) {
      const mid = 0.5 * (lo + hi);
      const p = at(mid);
      if (Math.abs(p - target) < 1e-8) return mid;
      if ((p < target) === increasing) lo = mid; else hi = mid;
    }
    return 0.5 * (lo + hi);
  }

  /* Extrinsic value remaining at each checkpoint, holding spot flat. */
  function decaySchedule(spot, strike, days, vol, rate, kind, checkpoints) {
    const points = checkpoints || [45, 30, 21, 14, 7, 3, 1];
    const today = blackScholes(spot, strike, days, vol, rate, kind);
    if (!today) return [];
    const rows = [];
    points.forEach(dte => {
      if (dte > days) return;
      const g = blackScholes(spot, strike, dte, vol, rate, kind);
      if (!g) return;
      rows.push({
        dte: dte,
        extrinsic: g.extrinsic,
        pctOfToday: today.extrinsic > 0 ? g.extrinsic / today.extrinsic * 100 : 0,
      });
    });
    return rows;
  }

  /*
   * Probability the underlying ends at or beyond `target` at expiry, under the
   * risk-neutral measure.
   *
   * Worth being blunt about what this is: the market's own pricing of that
   * outcome, not a forecast. It has no view, it embeds no drift you believe in,
   * and it is exactly the number the option's price already reflects. It is
   * useful for ranking rungs of a ladder against each other, and misleading if
   * read as "my odds".
   */
  function finishProbability(spot, target, vol, days, rate) {
    if (!(spot > 0) || !(target > 0) || !(vol > 0) || !(days > 0)) return null;
    rate = rate == null ? 0.045 : rate;
    const years = days / DAYS_PER_YEAR;
    const d = (Math.log(spot / target) + (rate - 0.5 * vol * vol) * years) /
              (vol * Math.sqrt(years));
    return target >= spot ? normCdf(d) : 1 - normCdf(d);
  }

  /*
   * Probability the underlying touches `target` at any point before expiry.
   *
   * For driftless Brownian motion the reflection principle gives
   * P(max > b) = 2 P(end > b), which is why a level you would only finish
   * beyond one time in five is touched closer to two times in five. Capped at
   * 1, and the drift term is dropped rather than approximated — keeping it
   * would imply a precision this identity does not have.
   */
  function touchProbability(spot, target, vol, days) {
    if (!(spot > 0) || !(target > 0) || !(vol > 0) || !(days > 0)) return null;
    if (target === spot) return 1;
    const years = days / DAYS_PER_YEAR;
    const d = Math.abs(Math.log(target / spot)) / (vol * Math.sqrt(years));
    return Math.min(1, 2 * normCdf(-d));
  }

  /* ------------------------------------------------------------------ ladders */

  /*
   * Reprice the position across a grid of underlying moves.
   *
   * `holdDays` is how far into the future to evaluate, so the same table
   * answers both halves of the question the greeks only answer locally: what a
   * move does to the premium, and what waiting does to it. Delta and gamma
   * describe the first step away from spot; this walks the whole curve, so a
   * 10% move is priced as 10% rather than as ten times delta.
   */
  function moveLadder(pos, opts) {
    const o = opts || {};
    const step = o.stepPct || 1;
    const max = o.maxPct == null ? 10 : o.maxPct;
    const holdDays = o.holdDays || 0;
    const contracts = pos.contracts || 1;
    const mult = pos.multiplier == null ? 100 : pos.multiplier;
    const daysLeft = pos.days - holdDays;
    const rows = [];

    for (let pct = -max; pct <= max + 1e-9; pct += step) {
      const spot = pos.spot * (1 + pct / 100);
      const g = blackScholes(spot, pos.strike, daysLeft, pos.vol, pos.rate, pos.kind);
      const premium = g ? g.price
        : Math.max(0, pos.kind === "put" ? pos.strike - spot : spot - pos.strike);
      // Solving the volatility out of the premium leaves picodollar residue at
      // the centre row, which formats as "-$0.00". Below a cent it is zero.
      let pnl = (premium - pos.premium) * contracts * mult;
      if (Math.abs(pnl) < 0.005) pnl = 0;
      rows.push({
        movePct: pct,
        spot: spot,
        premium: premium,
        premiumPct: pos.premium > 0
          ? (Math.abs(premium - pos.premium) < 1e-6 ? 0 : (premium / pos.premium - 1) * 100)
          : null,
        pnl: pnl,
        pnlPct: pos.premium > 0 ? pnl / (pos.premium * contracts * mult) * 100 : null,
        delta: g ? g.delta : null,
        theta: g ? g.theta * contracts * mult : null,
        pTouch: pct === 0 ? 1 : touchProbability(pos.spot, spot, pos.vol, pos.days),
      });
    }
    return rows;
  }

  /*
   * The profit-taking ladder: for each target gain on the premium, what has to
   * happen and how likely it is.
   *
   * `scaleOut` is the part a spreadsheet cannot do without a solver. At each
   * rung it reports how many contracts to sell to bank the entire cost basis —
   * the point at which the rest of the position is playing with the market's
   * money rather than yours.
   */
  function profitLadder(pos, opts) {
    const o = opts || {};
    const step = o.stepPct || 10;
    const max = o.maxPct == null ? 100 : o.maxPct;
    const contracts = pos.contracts || 1;
    const mult = pos.multiplier == null ? 100 : pos.multiplier;
    const cost = pos.premium * contracts * mult;
    const holdDays = o.holdDays || 0;
    const daysLeft = pos.days - holdDays;
    const rows = [];

    for (let pct = step; pct <= max + 1e-9; pct += step) {
      const target = pos.premium * (1 + pct / 100);
      const spotNeeded = breakevenSpot(target, pos.strike, daysLeft, pos.vol, pos.rate, pos.kind);
      const gain = (target - pos.premium) * contracts * mult;
      const perContract = (target - pos.premium) * mult;
      rows.push({
        gainPct: pct,
        sellPremium: target,
        spotNeeded: spotNeeded,
        spotMovePct: spotNeeded == null ? null : (spotNeeded / pos.spot - 1) * 100,
        gain: gain,
        exitValue: target * contracts * mult,
        rMultiple: pos.risk > 0 ? gain / pos.risk : null,
        // Whole contracts to sell so the cash taken off the table covers what
        // the position cost — the point past which the rest rides on the
        // market's money rather than yours. Rounded up and capped at the
        // position, because half a contract is not a trade: on a one-lot the
        // answer is always the whole thing, and saying so is the useful reply.
        contractsToRecoverCost: target > 0
          ? Math.min(contracts, Math.ceil(cost / (target * mult)))
          : null,
        pTouch: spotNeeded == null ? null
          : touchProbability(pos.spot, spotNeeded, pos.vol, pos.days),
        pFinish: spotNeeded == null ? null
          : finishProbability(pos.spot, spotNeeded, pos.vol, pos.days, pos.rate),
      });
    }
    return rows;
  }

  /*
   * What waiting costs, with the underlying pinned. The horizons are the ones
   * a trader actually asks about — an hour into the session, overnight, a week
   * — expressed in dollars on the position rather than in per-share theta,
   * because theta per share on a five-lot is not the number that hurts.
   */
  function decayStrip(pos, horizons) {
    const points = horizons || [
      { label: "1 hour", days: 1 / 24 },
      { label: "1 session", days: 1 },
      { label: "3 sessions", days: 3 },
      { label: "1 week", days: 7 },
      { label: "2 weeks", days: 14 },
    ];
    const contracts = pos.contracts || 1;
    const mult = pos.multiplier == null ? 100 : pos.multiplier;
    const now = blackScholes(pos.spot, pos.strike, pos.days, pos.vol, pos.rate, pos.kind);
    if (!now) return [];
    return points.filter(h => h.days < pos.days).map(h => {
      const g = blackScholes(pos.spot, pos.strike, pos.days - h.days, pos.vol, pos.rate, pos.kind);
      const premium = g ? g.price : 0;
      return {
        label: h.label,
        days: h.days,
        premium: premium,
        lost: (now.price - premium) * contracts * mult,
        lostPct: now.price > 0 ? (now.price - premium) / now.price * 100 : 0,
      };
    });
  }

  return {
    DAYS_PER_YEAR: DAYS_PER_YEAR,
    TRADING_DAYS: TRADING_DAYS,
    normCdf: normCdf,
    normPdf: normPdf,
    blackScholes: blackScholes,
    impliedVol: impliedVol,
    expectedMove: expectedMove,
    hurdleRatio: hurdleRatio,
    breakevenSpot: breakevenSpot,
    decaySchedule: decaySchedule,
    finishProbability: finishProbability,
    touchProbability: touchProbability,
    moveLadder: moveLadder,
    profitLadder: profitLadder,
    decayStrip: decayStrip,
  };
});
